# Shift pattern by 3
row = 16
output = [[0]*row for _ in range(row)]

# Input diagonal: y = x + 2, shifted by 3: y = x + 5
for x in range(16):
    y = x + 5
    if 0 <= y < 16:
        output[y][x] = 1

# Input 9s at anti-diagonals 14 and 16, shifted by 3: 17 and 19
# Anti-diagonal sum = y + x
for s in [17, 19]:
    for x in range(16):
        y = s - x
        if 0 <= y < 16:
            output[y][x] = 9
            break  # First occurrence

# Input 2 at anti-diagonal 15, shifted by 3: 18
for x in range(16):
    y = 18 - x
    if 0 <= y < 16:
        output[y][x] = 2
        break

print("Shifted pattern:")
for l in output:
    print(' '.join(str(c) for c in l))

